insert into public.roles (id, name, team, ability, glyph, reminders, edition, is_official) values
  ('washerwoman', '洗衣妇', 'townsfolk', '开局时，你会得知两名玩家中有一名是某个特定的镇民角色。', '洗', array['镇民', '错误']::text[], 'tb', true),
  ('librarian', '图书管理员', 'townsfolk', '开局时，你会得知两名玩家中有一名是某个特定的外来者角色；或得知场上没有外来者。', '图', array['外来者', '错误']::text[], 'tb', true),
  ('investigator', '调查员', 'townsfolk', '开局时，你会得知两名玩家中有一名是某个特定的爪牙角色。', '调', array['爪牙', '错误']::text[], 'tb', true),
  ('chef', '厨师', 'townsfolk', '开局时，你会得知场上有多少对相邻而坐的邪恶玩家。', '厨', array[]::text[], 'tb', true),
  ('empath', '共情者', 'townsfolk', '每个夜晚，你会得知与你相邻的两名存活玩家之中，有几名属于邪恶阵营。', '共', array[]::text[], 'tb', true),
  ('fortuneteller', '占卜师', 'townsfolk', '每个夜晚，选择两名玩家：你会得知其中是否有恶魔。有一名善良玩家会始终被你当作恶魔。', '占', array['红鲱鱼']::text[], 'tb', true),
  ('undertaker', '送葬者', 'townsfolk', '每个夜晚（首夜除外），你会得知当天白天被处决的玩家的角色。', '葬', array['已处决']::text[], 'tb', true),
  ('monk', '僧侣', 'townsfolk', '每个夜晚（首夜除外），选择一名其他玩家：今晚恶魔无法杀死该玩家。', '僧', array['受保护']::text[], 'tb', true),
  ('ravenkeeper', '守鸦人', 'townsfolk', '如果你在夜晚死亡，你会被唤醒并选择一名玩家：你会得知其角色。', '鸦', array[]::text[], 'tb', true),
  ('virgin', '圣女', 'townsfolk', '你第一次被提名时，如果提名者是镇民，提名者立即被处决。', '圣', array['失去能力']::text[], 'tb', true),
  ('slayer', '杀手', 'townsfolk', '每局游戏限一次，你可以在白天公开选择一名玩家：如果其是恶魔，其死亡。', '杀', array['失去能力']::text[], 'tb', true),
  ('soldier', '士兵', 'townsfolk', '恶魔无法杀死你。', '兵', array[]::text[], 'tb', true),
  ('mayor', '镇长', 'townsfolk', '如果只剩三名玩家存活且当天没有处决，你的阵营获胜。你在夜晚将要死亡时，可能改由另一名玩家死亡。', '镇', array[]::text[], 'tb', true),
  ('butler', '管家', 'outsider', '每个夜晚，选择一名其他玩家作为你的主人：明天只有当你的主人投票时，你才能投票。', '管', array['主人']::text[], 'tb', true),
  ('drunk', '酒鬼', 'outsider', '你不知道自己是酒鬼。你以为自己是某个镇民角色，但你的能力不会生效。', '酒', array[]::text[], 'tb', true),
  ('recluse', '陌客', 'outsider', '你可能会被当作邪恶阵营、爪牙或恶魔，即使你已死亡。', '陌', array[]::text[], 'tb', true),
  ('saint', '圣徒', 'outsider', '如果你因处决而死亡，你的阵营落败。', '徒', array[]::text[], 'tb', true),
  ('poisoner', '投毒者', 'minion', '每个夜晚，选择一名玩家：其在当晚和次日白天中毒。', '毒', array['中毒']::text[], 'tb', true),
  ('spy', '间谍', 'minion', '每个夜晚，你可以查看魔典。你可能会被当作善良阵营、镇民或外来者，即使你已死亡。', '谍', array[]::text[], 'tb', true),
  ('scarletwoman', '红唇女郎', 'minion', '如果恶魔死亡时存活玩家不少于五人，你成为新的恶魔。', '红', array['恶魔']::text[], 'tb', true),
  ('baron', '男爵', 'minion', '场上额外多出两名外来者。〔+2 外来者〕', '爵', array[]::text[], 'tb', true),
  ('imp', '小恶魔', 'demon', '每个夜晚（首夜除外），选择一名玩家：其死亡。如果你以此杀死自己，一名爪牙会成为小恶魔。', '魔', array['死亡']::text[], 'tb', true),
  ('grandmother', '祖母', 'townsfolk', '开局时，你会得知一名善良玩家及其角色。如果恶魔杀死了该玩家，你也会死亡。', '祖', array['孙子']::text[], 'bmr', true),
  ('sailor', '水手', 'townsfolk', '每个夜晚，选择一名存活玩家：你们两人之一会醉酒直到次日黄昏。你无法死亡。', '水', array['醉酒']::text[], 'bmr', true),
  ('chambermaid', '侍女', 'townsfolk', '每个夜晚，选择两名存活的其他玩家：你会得知他们之中有几人今晚因自身能力而被唤醒。', '侍', array[]::text[], 'bmr', true),
  ('exorcist', '驱魔人', 'townsfolk', '每个夜晚（首夜除外），选择一名玩家（不能与上一晚相同）：如果其是恶魔，恶魔会得知你是谁，且今晚不会醒来。', '驱', array['已选择']::text[], 'bmr', true),
  ('innkeeper', '旅店老板', 'townsfolk', '每个夜晚（首夜除外），选择两名玩家：他们今晚无法死亡，但其中一人会醉酒直到次日黄昏。', '旅', array['受保护', '醉酒']::text[], 'bmr', true),
  ('gambler', '赌徒', 'townsfolk', '每个夜晚（首夜除外），选择一名玩家并猜测其角色：如果猜错，你死亡。', '赌', array[]::text[], 'bmr', true),
  ('gossip', '造谣者', 'townsfolk', '每个白天，你可以公开发表一个陈述。如果该陈述为真，今晚会有一名玩家死亡。', '谣', array[]::text[], 'bmr', true),
  ('courtier', '侍臣', 'townsfolk', '每局游戏限一次，在夜晚选择一个角色：该角色的持有者会醉酒三天三夜。', '臣', array['醉酒', '失去能力']::text[], 'bmr', true),
  ('professor', '教授', 'townsfolk', '每局游戏限一次，在夜晚（首夜除外）选择一名死亡的玩家：如果其是镇民，其复活。', '教', array['复活', '失去能力']::text[], 'bmr', true),
  ('minstrel', '吟游诗人', 'townsfolk', '当一名爪牙因处决而死亡时，除你以外的所有玩家会醉酒直到次日黄昏。', '吟', array['全员醉酒']::text[], 'bmr', true),
  ('tealady', '茶艺师', 'townsfolk', '如果与你相邻的两名存活玩家都是善良的，他们无法死亡。', '茶', array[]::text[], 'bmr', true),
  ('pacifist', '和平主义者', 'townsfolk', '被处决的善良玩家可能不会死亡。', '和', array[]::text[], 'bmr', true),
  ('fool', '弄臣', 'townsfolk', '你第一次将要死亡时，你不会死亡。', '弄', array['失去能力']::text[], 'bmr', true),
  ('tinker', '修补匠', 'outsider', '你随时可能死亡。', '补', array[]::text[], 'bmr', true),
  ('moonchild', '月之子', 'outsider', '当你得知自己死亡时，公开选择一名存活玩家：如果其是善良的，其在当晚死亡。', '月', array[]::text[], 'bmr', true),
  ('goon', '莽夫', 'outsider', '每个夜晚，第一个以自身能力选择你的玩家当晚醉酒。你会转变为该玩家的阵营。', '莽', array['醉酒']::text[], 'bmr', true),
  ('lunatic', '疯子', 'outsider', '你以为自己是恶魔，但其实不是。真正的恶魔知道你是谁，以及你在夜晚选择了谁。', '疯', array[]::text[], 'bmr', true),
  ('godfather', '教父', 'minion', '开局时，你会得知场上有哪些外来者。如果当天有外来者死亡，今晚选择一名玩家：其死亡。〔±1 外来者〕', '父', array['死亡']::text[], 'bmr', true),
  ('devilsadvocate', '魔鬼代言人', 'minion', '每个夜晚，选择一名存活玩家（不能与上一晚相同）：如果其明天被处决，其不会死亡。', '辩', array['受保护']::text[], 'bmr', true),
  ('assassin', '刺客', 'minion', '每局游戏限一次，在夜晚（首夜除外）选择一名玩家：其死亡，任何保护都对此无效。', '刺', array['失去能力']::text[], 'bmr', true),
  ('mastermind', '主谋', 'minion', '如果恶魔因处决而死亡并导致游戏结束，游戏改为再进行一天。如果当天有玩家被处决，其阵营落败。', '谋', array[]::text[], 'bmr', true),
  ('zombuul', '僵怖', 'demon', '每个夜晚（首夜除外），如果今天白天没有人死亡，选择一名玩家：其死亡。你第一次死亡时，你仍然存活，但会被当作已死亡。', '僵', array['死亡']::text[], 'bmr', true),
  ('pukka', '普卡', 'demon', '每个夜晚，选择一名玩家：其中毒。先前被你下毒的玩家死亡，然后恢复健康。', '普', array['中毒']::text[], 'bmr', true),
  ('shabaloth', '沙巴洛斯', 'demon', '每个夜晚（首夜除外），选择两名玩家：他们死亡。你昨晚杀死的一名玩家可能会复活。', '沙', array['死亡']::text[], 'bmr', true),
  ('po', '珀', 'demon', '每个夜晚（首夜除外），你可以选择一名玩家：其死亡。如果你上一次选择了不杀人，今晚改为选择三名玩家。', '珀', array['死亡', '蓄力']::text[], 'bmr', true),
  ('clockmaker', '钟表匠', 'townsfolk', '开局时，你会得知恶魔与离他最近的爪牙之间相隔几个座位。', '钟', array[]::text[], 'snv', true),
  ('dreamer', '筑梦师', 'townsfolk', '每个夜晚，选择一名除你以外的玩家：你会得知一个善良角色和一个邪恶角色，其中之一是该玩家的角色。', '梦', array[]::text[], 'snv', true),
  ('snakecharmer', '舞蛇人', 'townsfolk', '每个夜晚，选择一名存活玩家：如果你选中了恶魔，你们交换角色与阵营，然后其中毒。', '蛇', array['中毒']::text[], 'snv', true),
  ('mathematician', '数学家', 'townsfolk', '每个夜晚，你会得知自上个黎明以来，有多少名玩家的能力因其他角色的影响而未能正常生效。', '数', array[]::text[], 'snv', true),
  ('flowergirl', '卖花女孩', 'townsfolk', '每个夜晚（首夜除外），你会得知恶魔今天白天是否投过票。', '花', array['恶魔已投票']::text[], 'snv', true),
  ('towncrier', '城镇公告员', 'townsfolk', '每个夜晚（首夜除外），你会得知今天白天是否有爪牙发起过提名。', '告', array['爪牙已提名']::text[], 'snv', true),
  ('oracle', '神谕者', 'townsfolk', '每个夜晚（首夜除外），你会得知死亡的玩家之中有几名是邪恶的。', '谕', array[]::text[], 'snv', true),
  ('savant', '博学者', 'townsfolk', '每个白天，你可以私下拜访说书人，得知两条信息：一条为真，一条为假。', '博', array[]::text[], 'snv', true),
  ('seamstress', '女裁缝', 'townsfolk', '每局游戏限一次，在夜晚选择两名其他玩家：你会得知他们是否属于同一阵营。', '缝', array['失去能力']::text[], 'snv', true),
  ('philosopher', '哲学家', 'townsfolk', '每局游戏限一次，在夜晚选择一个善良角色：你获得该角色的能力。如果该角色在场，其持有者醉酒。', '哲', array['醉酒', '失去能力']::text[], 'snv', true),
  ('artist', '艺术家', 'townsfolk', '每局游戏限一次，在白天私下向说书人提出任意一个是非问题：你会得知答案。', '艺', array['失去能力']::text[], 'snv', true),
  ('juggler', '杂耍艺人', 'townsfolk', '在你的第一个白天，公开猜测至多五名玩家的角色。当晚，你会得知猜对了几个。', '杂', array['猜对']::text[], 'snv', true),
  ('sage', '贤者', 'townsfolk', '如果恶魔杀死了你，你会被唤醒，得知两名玩家中有一名是恶魔。', '贤', array[]::text[], 'snv', true),
  ('mutant', '畸形秀演员', 'outsider', '如果你“疯狂地”证明自己是外来者，你可能会被处决。', '畸', array[]::text[], 'snv', true),
  ('sweetheart', '心上人', 'outsider', '当你死亡时，会有一名玩家从此醉酒。', '心', array['醉酒']::text[], 'snv', true),
  ('barber', '理发师', 'outsider', '如果你死亡，当晚恶魔可以选择两名玩家（不能是另一名恶魔）交换角色。', '理', array['理发']::text[], 'snv', true),
  ('klutz', '呆瓜', 'outsider', '当你得知自己死亡时，公开选择一名存活玩家：如果其是邪恶的，你的阵营落败。', '呆', array[]::text[], 'snv', true),
  ('eviltwin', '镜像双子', 'minion', '你与一名对立阵营的玩家互相知道对方的身份。如果善良的双子被处决，邪恶阵营获胜。只要你们都存活，善良阵营无法获胜。', '双', array['双子']::text[], 'snv', true),
  ('witch', '女巫', 'minion', '每个夜晚，选择一名玩家：如果其明天发起提名，其死亡。当只剩三名玩家存活时，你失去此能力。', '巫', array['诅咒']::text[], 'snv', true),
  ('cerenovus', '洗脑师', 'minion', '每个夜晚，选择一名玩家和一个善良角色：其明天必须“疯狂地”证明自己是该角色，否则可能被处决。', '脑', array['疯狂']::text[], 'snv', true),
  ('pithag', '麻脸巫婆', 'minion', '每个夜晚（首夜除外），选择一名玩家和一个不在场的角色：其变为该角色。如果因此产生了恶魔，当晚的死亡由说书人决定。', '麻', array[]::text[], 'snv', true),
  ('fanggu', '方古', 'demon', '每个夜晚（首夜除外），选择一名玩家：其死亡。你第一次以此杀死外来者时，该玩家成为邪恶的方古，而你死亡。〔+1 外来者〕', '方', array['死亡', '已转化']::text[], 'snv', true),
  ('vigormortis', '亡骨魔', 'demon', '每个夜晚（首夜除外），选择一名玩家：其死亡。被你杀死的爪牙保留能力，并使一名与其相邻的镇民中毒。〔-1 外来者〕', '骨', array['死亡', '保留能力', '中毒']::text[], 'snv', true),
  ('nodashii', '诺-达鲺', 'demon', '每个夜晚（首夜除外），选择一名玩家：其死亡。与你距离最近的两名镇民中毒。', '诺', array['中毒', '死亡']::text[], 'snv', true),
  ('vortox', '涡流', 'demon', '每个夜晚（首夜除外），选择一名玩家：其死亡。镇民角色获得的信息都是错误的。每个白天，如果没有人被处决，邪恶阵营获胜。', '涡', array['死亡']::text[], 'snv', true),
  ('lycanthrope', '半兽人', 'townsfolk', '每个夜晚*，你要选择一名存活玩家：如果他是善良的，他死亡，并且当晚恶魔不会造成死亡。会有一名善良玩家始终被当作邪恶阵营。', '兽', array['失足', '死亡']::text[], 'exp', true),
  ('banshee', '报丧女妖', 'townsfolk', '如果恶魔杀死了你，所有玩家都会得知此事。从现在开始，你每天可以发起两次提名，每次投票时可以投两票。', '报', array['具有能力']::text[], 'exp', true),
  ('choirboy', '唱诗男孩', 'townsfolk', '如果恶魔杀死了国王，你会得知哪名玩家是恶魔。[+国王]', '唱', array[]::text[], 'exp', true),
  ('preacher', '传教士', 'townsfolk', '每个夜晚，你要选择一名玩家：如果你选中了爪牙，他会得知被传教士选中。所有被你选中的爪牙失去能力。', '传', array['失去能力']::text[], 'exp', true),
  ('villageidiot', '村夫', 'townsfolk', '每个夜晚，你要选择一名玩家：你会得知他的阵营。[+0~2村夫，复数村夫中有一人醉酒]', '村', array['醉酒']::text[], 'exp', true),
  ('engineer', '工程师', 'townsfolk', '每局游戏限一次，在夜晚时，你可以选择让恶魔变成你选择的恶魔角色，或让所有爪牙变成你选择的爪牙角色。', '工', array['失去能力']::text[], 'exp', true),
  ('princess', '公主', 'townsfolk', '在你的首个白天，如果你提名并处决了一名玩家，当晚恶魔不会造成死亡。', '公', array['没有死亡']::text[], 'exp', true),
  ('noble', '贵族', 'townsfolk', '在你的首个夜晚，你会得知三名玩家：其中有且只有一名玩家是邪恶的。', '贵', array['得知']::text[], 'exp', true),
  ('king', '国王', 'townsfolk', '每个夜晚，如果死亡的玩家数量大于或等于存活的玩家数量，你会得知一个存活的角色。恶魔知道你是国王。', '国', array[]::text[], 'exp', true),
  ('general', '将军', 'townsfolk', '每个夜晚，你会得知说书人认为哪个阵营当前更有优势（善良/邪恶/均势）。', '将', array[]::text[], 'exp', true),
  ('alchemist', '炼金术士', 'townsfolk', '你拥有一个爪牙角色的能力。当你使用能力时，说书人可能会要求你更换选择。', '炼', array['是炼金术士']::text[], 'exp', true),
  ('magician', '魔术师', 'townsfolk', '恶魔会以为你是爪牙。爪牙会以为你是恶魔。', '术', array[]::text[], 'exp', true),
  ('farmer', '农夫', 'townsfolk', '当你在夜晚死亡时，一名存活的善良玩家会变成农夫。', '农', array[]::text[], 'exp', true),
  ('highpriestess', '女祭司', 'townsfolk', '每个夜晚，你会得知一名说书人认为你最应该与其交流的玩家。', '祭', array[]::text[], 'exp', true),
  ('balloonist', '气球驾驶员', 'townsfolk', '每个夜晚，你会得知一名与上个夜晚得知的玩家角色类型不同的玩家。[+0~1外来者]', '球', array['得知']::text[], 'exp', true),
  ('knight', '骑士', 'townsfolk', '在你的首个夜晚，你会得知两名非恶魔玩家。', '骑', array['得知']::text[], 'exp', true),
  ('bountyhunter', '赏金猎人', 'townsfolk', '在你的首个夜晚，你会得知一名邪恶玩家。每当你得知的玩家死亡，你会在当晚得知另一名邪恶玩家。[会有一名镇民转变为邪恶阵营]', '赏', array['得知']::text[], 'exp', true),
  ('amnesiac', '失忆者', 'townsfolk', '你不知道你的能力是什么。每个白天你可以找说书人猜测一次，你会得知你的猜测有多准确。', '忆', array['？']::text[], 'exp', true),
  ('cannibal', '食人族', 'townsfolk', '你拥有上个死于处决的玩家的能力。如果该玩家属于邪恶阵营，你中毒直到下个善良玩家死于处决。', '族', array['饱餐', '中毒']::text[], 'exp', true),
  ('steward', '事务官', 'townsfolk', '在你的首个夜晚，你会得知一名善良玩家。', '事', array['得知']::text[], 'exp', true),
  ('nightwatchman', '守夜人', 'townsfolk', '每局游戏限一次，在夜晚时，你可以选择一名玩家：他会得知你是守夜人。', '守', array['失去能力']::text[], 'exp', true),
  ('atheist', '无神论者', 'townsfolk', '说书人可以打破游戏规则，如果说书人被处决，善良阵营获胜，即使你已死亡。[无邪恶角色在场]', '无', array[]::text[], 'exp', true),
  ('alsaahir', '戏法师', 'townsfolk', '每个白天，你可以公开进行一次谁是爪牙，谁是恶魔的猜测。如果你猜对，善良阵营获胜。', '法', array[]::text[], 'exp', true),
  ('pixie', '小精灵', 'townsfolk', '在你的首个夜晚，你会得知一个在场的镇民角色。如果你“疯狂”地证明你是该角色，当他死亡时你获得该角色的能力。', '精', array['疯狂', '获得能力']::text[], 'exp', true),
  ('shugenja', '修行者', 'townsfolk', '在你的首个夜晚，你会得知距离最近的邪恶玩家位于你的顺时针还是逆时针方向。如果两侧的邪恶玩家与你距离相等，你得知的信息由说书人决定。', '修', array[]::text[], 'exp', true),
  ('huntsman', '巡山人', 'townsfolk', '每局游戏限一次，在夜晚时，你可以选择一名存活的玩家：如果你选中了落难少女，她会变成一个不在场的镇民角色。[+落难少女]', '巡', array['失去能力']::text[], 'exp', true),
  ('cultleader', '异教领袖', 'townsfolk', '每个夜晚，你会转变为与你邻近的一名存活的玩家的阵营。每个白天，你可以提议所有玩家加入你的教派，如果所有善良玩家同意加入，你的阵营获胜。', '异', array[]::text[], 'exp', true),
  ('poppygrower', '罂粟种植者', 'townsfolk', '爪牙和恶魔互相不认识。如果你死亡，当晚他们会互相认识。', '罂', array['唤醒邪恶']::text[], 'exp', true),
  ('fisherman', '渔夫', 'townsfolk', '每局游戏限一次，在白天时，你可以让说书人给你一些能帮助你的阵营获胜的建议。', '渔', array['失去能力']::text[], 'exp', true),
  ('acrobat', '杂技演员', 'townsfolk', '每个夜晚*，你要选择一名玩家：如果当晚他醉酒或中毒，你死亡。', '技', array['被选择', '死亡']::text[], 'exp', true),
  ('snitch', '告密者', 'outsider', '爪牙会在其首个夜晚得知三个伪装。', '密', array[]::text[], 'exp', true),
  ('puzzlemaster', '解谜大师', 'outsider', '一名玩家醉酒，即使你已死亡。每局游戏限一次，你可以猜测谁是那个醉酒的玩家，如果猜对了，你会得知谁是恶魔，但如果猜错了，你会得知错误的“谁是恶魔”信息。', '谜', array['醉酒', '已猜测']::text[], 'exp', true),
  ('zealot', '狂热者', 'outsider', '如果有大于等于五名玩家存活，你必须在所有提名中投票。', '狂', array[]::text[], 'exp', true),
  ('damsel', '落难少女', 'outsider', '所有爪牙都知道落难少女在场。每局游戏限一次，任意爪牙可以公开猜测你是落难少女，如果猜对，你的阵营落败。', '落', array['已被猜测']::text[], 'exp', true),
  ('hatter', '帽匠', 'outsider', '如果你死亡，当晚爪牙和恶魔玩家可以选择变成新的爪牙和恶魔角色。', '帽', array['今晚茶会']::text[], 'exp', true),
  ('golem', '魔像', 'outsider', '每局游戏你只能发起提名一次。当你发起提名时，如果被你提名的玩家不是恶魔，他死亡。', '像', array['无法提名']::text[], 'exp', true),
  ('ogre', '食人魔', 'outsider', '在你的首个夜晚，你要选择除你以外的一名玩家：你转变为他的阵营，即使你已醉酒或中毒，但你不知道你转变后的阵营。', '食', array['挚友']::text[], 'exp', true),
  ('plaguedoctor', '瘟疫医生', 'outsider', '当你死亡时，说书人会获得一个爪牙能力。', '瘟', array['说书人能力']::text[], 'exp', true),
  ('heretic', '异端分子', 'outsider', '对调胜负结果，即使你已死亡。', '端', array[]::text[], 'exp', true),
  ('hermit', '隐士', 'outsider', '你拥有所有外来者能力。[-0~1外来者]', '隐', array['1', '2', '3']::text[], 'exp', true),
  ('politician', '政客', 'outsider', '如果你是对你的阵营落败负最大责任的人，你转变阵营并获胜，即使你已死亡。', '政', array[]::text[], 'exp', true),
  ('goblin', '哥布林', 'minion', '如果你在被提名后公开声明自己是哥布林且在那个白天被处决，你的阵营获胜。', '哥', array['已宣称']::text[], 'exp', true),
  ('widow', '寡妇', 'minion', '在你的首个夜晚，你能查看魔典并选择一名玩家：他中毒。随后，始终会有一名善良玩家知道寡妇在场。', '寡', array['中毒', '得知']::text[], 'exp', true),
  ('organgrinder', '街头风琴手', 'minion', '所有玩家在投票时闭眼，且票数会秘密统计。每个夜晚，你要选择自己是否醉酒直到下个黄昏。', '街', array['即将被处决', '醉酒']::text[], 'exp', true),
  ('psychopath', '精神病患者', 'minion', '每个白天，在提名开始前，你可以公开选择一名玩家：他死亡。如果你被处决，提名你的玩家需要和你猜拳，只有你输了你才会死亡。', '病', array[]::text[], 'exp', true),
  ('boffin', '科学怪人', 'minion', '恶魔拥有一个不在场的善良角色的能力，即使他醉酒或中毒。你和他都知道他获得了什么能力。', '科', array[]::text[], 'exp', true),
  ('fearmonger', '恐惧之灵', 'minion', '每个夜晚，你要选择一名玩家：如果你提名他且他被处决，他的阵营落败。当你首次选择或更换目标时，所有玩家都会得知你选择了新的玩家。', '恐', array['恐惧']::text[], 'exp', true),
  ('mezepheles', '灵言师', 'minion', '在你的首个夜晚，你会得知一个关键词。首个说出该关键词的善良玩家会在当晚转变为邪恶阵营。', '灵', array['转为邪恶', '失去能力']::text[], 'exp', true),
  ('marionette', '提线木偶', 'minion', '你以为你是一个善良角色，但其实你不是。恶魔会知道你是提线木偶。[提线木偶会与恶魔邻座]', '偶', array['是提线木偶']::text[], 'exp', true),
  ('wraith', '亡魂', 'minion', '你可以在夜晚睁眼。当其他邪恶玩家被唤醒时，你也会被唤醒。', '亡', array[]::text[], 'exp', true),
  ('vizier', '维齐尔', 'minion', '所有玩家都知道你是维齐尔。你在白天时不会死亡。如果一次提名中有善良玩家投票，你可以让被提名者立即被处决。', '维', array[]::text[], 'exp', true),
  ('wizard', '巫师', 'minion', '每局游戏限一次，你可以向说书人许愿。如果愿望被实现，可能会伴随着代价和线索。', '师', array['？']::text[], 'exp', true),
  ('xaan', '限', 'minion', '在等同于初始外来者数量的夜晚，所有镇民玩家中毒直到下个黄昏。[外来者数量任意]', '限', array['第一晚', '第二晚', '第三晚', '大限将至']::text[], 'exp', true),
  ('harpy', '鹰身女妖', 'minion', '每个夜晚，你要选择两名玩家：明天第一名玩家需要“疯狂”地证明第二名玩家是邪恶的，否则他们之中可能会有人死亡。', '鹰', array['疯狂', '第二名']::text[], 'exp', true),
  ('boomdandy', '炸弹人', 'minion', '如果你被处决，除三名玩家以外的其他所有玩家均会死亡。倒数十声后，被最多玩家手指指着的玩家死亡。', '炸', array[]::text[], 'exp', true),
  ('summoner', '召唤师', 'minion', '在首个夜晚，你会得知三个伪装。在第三个夜晚，你要选择一名玩家：他变成由你选择的邪恶恶魔。[无恶魔在场]', '召', array['第一晚', '第二晚', '第三晚']::text[], 'exp', true),
  ('ojo', '奥赫', 'demon', '每个夜晚*，你要选择一个角色：他死亡。如果该角色不在场，则由说书人来决定谁会被你杀死。', '奥', array['死亡']::text[], 'exp', true),
  ('riot', '暴乱', 'demon', '在第三个白天，所有爪牙会变成暴乱，当天被提名的玩家会立即死亡且必须再次提名一名存活的玩家。', '乱', array[]::text[], 'exp', true),
  ('lordoftyphon', '堤丰之首', 'demon', '每个夜晚*，你要选择一名玩家：他死亡。[邪恶角色全部邻座，你靠近正中，+1爪牙，-或+任意数量外来者]', '堤', array['死亡']::text[], 'exp', true),
  ('alhadikhia', '哈迪寂亚', 'demon', '每个夜晚*，你可以选择三名玩家（所有玩家都会得知你选了谁）：他们分别秘密决定自己的生死，然后如果他们都存活则都死亡。', '哈', array['1', '2', '3', '选择生', '选择死']::text[], 'exp', true),
  ('legion', '军团', 'demon', '每个夜晚*，可能有一名玩家死亡。如果一项提名只有邪恶玩家投票，投票无效。你也会被当作是爪牙。[多数玩家为军团]', '军', array['即将被处决', '死亡']::text[], 'exp', true),
  ('kazali', '卡扎力', 'demon', '每个夜晚*，你要选择一名玩家：他死亡。[由你决定谁是什么爪牙，-或+任意数量外来者]', '卡', array['死亡']::text[], 'exp', true),
  ('leviathan', '利维坦', 'demon', '如果多于一名善良玩家被处决，邪恶阵营获胜。所有玩家都知道利维坦在场。在第五个白天结束时，邪恶阵营获胜。', '利', array['第一天', '第二天', '第三天', '第四天', '第五天', '善良被处决']::text[], 'exp', true),
  ('lleech', '痢蛭', 'demon', '每个夜晚*，你要选择一名玩家：他死亡。在你的首个夜晚，你要选择一名存活的玩家：他中毒，只有当他处于死亡状态时你才会立即死亡。', '痢', array['中毒', '死亡']::text[], 'exp', true),
  ('lilmonsta', '小怪宝', 'demon', '每个夜晚，所有爪牙要秘密决定由哪名玩家来照看小怪宝并且“是恶魔”。每个夜晚*，可能会有一名玩家死亡。[+1爪牙]', '怪', array['是恶魔', '死亡']::text[], 'exp', true),
  ('yaggababble', '牙噶巴卜', 'demon', '在你的首个夜晚，你会得知一段秘密短语。每次你在白天公开说出这段短语，当天便可能会有一名玩家在这之后死亡。', '牙', array['死亡']::text[], 'exp', true),
  ('banxian', '半仙', 'townsfolk', '任何在夜晚使用自身能力选择你的其他玩家，会改为选中另一名邪恶玩家作为替代。', '仙', array[]::text[], 'hdcs', true),
  ('bianlianshi', '变脸师', 'townsfolk', '每个白天，如果你“疯狂”地证明自己是一个善良角色（与之前不同），你可能会在当晚获得那个角色的能力，直到下个黄昏。', '变', array['是变脸师']::text[], 'hdcs', true),
  ('dagengren', '打更人', 'townsfolk', '每个夜晚*，你要猜测今晚首个死亡的玩家与你的距离。如果你猜测正确，则除你以外的所有玩家今晚不会死亡，但你可能会死亡。', '更', array['警惕', '死亡']::text[], 'hdcs', true),
  ('dianxiaoer', '店小二', 'townsfolk', '在你的首个夜晚，你会得知两名善良玩家。他们之中会有一人醉酒，即使你已死亡。', '店', array['熟客', '醉酒']::text[], 'hdcs', true),
  ('geling', '歌伶', 'townsfolk', '每局游戏限一次，在白天时，你可以提议所有玩家观看你的演出，并从同意参加的玩家中选择你的观众。如果恶魔成为了观众，你会在当晚死亡。', '歌', array['失去能力', '死亡']::text[], 'hdcs', true),
  ('heshang', '和尚', 'townsfolk', '每个夜晚，当有邪恶玩家的能力首次选择或影响与你邻近的存活玩家时，改为此次能力不生效并持续至下个黎明，且你会得知你的能力被触发。', '尚', array['已生效']::text[], 'hdcs', true),
  ('jinyiwei', '锦衣卫', 'townsfolk', '每个夜晚*，你要选择一名玩家：如果他在下个黄昏前死亡，你代替他死亡。', '锦', array['保护']::text[], 'hdcs', true),
  ('langzhong', '郎中', 'townsfolk', '每个夜晚，你要选择除你以外的一名玩家：你会得知一个与他能力相关的词语。', '郎', array[]::text[], 'hdcs', true),
  ('qintianjian', '钦天监', 'townsfolk', '在你的首个夜晚，你会得知离你最近的邪恶玩家位于你的哪一侧（左/右/相同）。如果与你邻近的玩家中有邪恶阵营，你会得知错误信息作为替代。', '钦', array[]::text[], 'hdcs', true),
  ('wudaozhe', '悟道者', 'townsfolk', '你以为你是一个外来者，但你实际上不是。如果有邪恶玩家的能力选择或影响了你，你会立即变成一个不在场的镇民角色。', '悟', array['是悟道者']::text[], 'hdcs', true),
  ('xizi', '戏子', 'townsfolk', '所有戏子互相认识。不论在场的戏子数量多少或存活与否，胜负结果会被对调。[所有善良玩家都是戏子]', '戏', array[]::text[], 'hdcs', true),
  ('xionghaizi', '熊孩子', 'townsfolk', '每个夜晚，你要选择一个镇民角色：他的能力会产生错误信息，直到下个黄昏。', '熊', array['捣蛋']::text[], 'hdcs', true),
  ('yinyangshi', '阴阳师', 'townsfolk', '在你的首个夜晚，你会得知两个善良角色和两个邪恶角色，其中有且只有两个角色在场。', '阴', array['在场', '不在场']::text[], 'hdcs', true),
  ('nichen', '逆臣', 'outsider', '在你的首个夜晚，你要选择除你以外的一名玩家：如果他先死于处决，你会在当晚转变为邪恶；如果你先死于处决，他会在当晚转变为邪恶。', '逆', array['不共戴天']::text[], 'hdcs', true),
  ('shaxing', '煞星', 'outsider', '如果你死亡，当晚与你邻近的存活玩家之一可能会死亡。', '煞', array['死亡']::text[], 'hdcs', true),
  ('shijie', '使节', 'outsider', '每个夜晚限一次，一名玩家在使用自身能力选择邪恶玩家时会改为选中你，即使你已死亡。', '使', array['已触发']::text[], 'hdcs', true),
  ('shusheng', '书生', 'outsider', '恶魔知道书生在场。每局游戏限一次，恶魔可以拜访说书人并猜测你是书生。如果恶魔猜测正确，即使你已死亡，当晚该恶魔可以选择一名玩家：他死亡。', '书', array['已猜测', '死亡']::text[], 'hdcs', true),
  ('ganshiren', '赶尸人', 'minion', '与你邻近的两名镇民玩家会在其首次死亡时被当作仍然存活。[-1外来者]', '尸', array[]::text[], 'hdcs', true),
  ('humeiniang', '狐媚娘', 'minion', '在你的首个夜晚，你要选择一名玩家：他会知道狐媚娘在场。如果你死于处决，当晚他转变为邪恶阵营。', '狐', array['被魅惑']::text[], 'hdcs', true),
  ('jinweijun', '禁卫军', 'minion', '“疯狂”地想要死亡的玩家可能会立即被处决。', '禁', array[]::text[], 'hdcs', true),
  ('yangguren', '养蛊人', 'minion', '在你存活时提名你的玩家会在当晚死亡，即使你已死亡。', '蛊', array['蛊']::text[], 'hdcs', true),
  ('hundun', '混沌', 'demon', '每个夜晚*，你要选择一名玩家：他死亡。如果你以这种方式杀死了一名与你邻近的镇民玩家，除旅行者外的所有善良玩家会中毒直到下个黄昏。', '混', array['死亡', '善良中毒']::text[], 'hdcs', true),
  ('qiongqi', '穷奇', 'demon', '每个夜晚*，你要选择一名玩家：他死亡。如果今天白天有外来者死亡，当晚改为你要选择一名玩家：他死亡，但被当作仍然存活，随后会有一名其他玩家死亡。[+1外来者]', '穷', array['死于今日', '死亡']::text[], 'hdcs', true),
  ('taotie', '饕餮', 'demon', '每个夜晚*，你要选择任意数量的非旅行者玩家或一名旅行者玩家：如果他们的角色类型均不相同，他们死亡。[+1外来者]', '饕', array['死亡']::text[], 'hdcs', true),
  ('taowu', '梼杌', 'demon', '每个夜晚*，你要选择一名玩家：他死亡。当你将要死亡时，改为一名存活且具有能力的爪牙失去能力。你不会得知恶魔信息。', '梼', array['死亡', '失去能力']::text[], 'hdcs', true),
  ('bingbi', '秉笔', 'townsfolk', '如果你在白天死亡，当晚你会得知一名善良玩家。如果你在夜晚死亡，当晚你会得知一名邪恶玩家。', '秉', array['死于今日']::text[], 'hdcs', true),
  ('chongfei', '宠妃', 'townsfolk', '每局游戏限一次，说书人会在关于你的事情上打破规则。随后，你会秘密得知说书人为此做了什么。', '宠', array['失去能力', '恃宠而骄']::text[], 'hdcs', true),
  ('daoshi', '道士', 'townsfolk', '每个夜晚*，你要选择一名玩家：如果你选中了恶魔，你死亡，然后他醉酒直到下个黎明。', '道', array['死亡', '醉酒']::text[], 'hdcs', true),
  ('fangshi', '方士', 'townsfolk', '在你的首个夜晚，你要选择一个数字。在该数字对应的那一个夜晚，你会得知对应数量的在场角色。', '士', array['得知']::text[], 'hdcs', true),
  ('limao', '狸猫', 'townsfolk', '每个夜晚*，你要选择一名玩家：如果他是善良角色且当晚被邪恶角色杀死，你和他交换角色。', '狸', array['太子']::text[], 'hdcs', true),
  ('qianke', '掮客', 'townsfolk', '每个夜晚，你要选择两名存活玩家：如果他们阵营相同，今晚任何玩家使用自身能力选择他们之一作为目标时，改为选中另一名玩家。', '掮', array['熟客']::text[], 'hdcs', true),
  ('tixingguan', '提刑官', 'townsfolk', '在你首次提名玩家后，你会在当晚得知他的角色。恶魔会被你的能力当作善良角色。', '刑', array['已提名', '失去能力']::text[], 'hdcs', true),
  ('xuncha', '巡察', 'townsfolk', '每个夜晚*，你要选择两个善良角色（与上个夜晚都不同）：如果他们都存活，他们当晚不会死亡。', '察', array['巡防戍卫']::text[], 'hdcs', true),
  ('yinluren', '引路人', 'townsfolk', '每个夜晚，你要选择除你以外的至多三名玩家：你会得知今晚是否有邪恶玩家的能力选择或影响了他们之中的玩家。', '引', array[]::text[], 'hdcs', true),
  ('yishi', '驿使', 'townsfolk', '每个白天，你可以公开声明一个角色在场。在当晚，你会得知该声明是否正确。如果你得知过是和否，你失去此能力。', '驿', array['是', '否', '得知过是', '得知过否']::text[], 'hdcs', true),
  ('zhen', '鸩', 'townsfolk', '每局游戏限一次，在夜晚时*，你可以选择一个镇民角色：如果他在场，他中毒并死亡。', '鸩', array['中毒', '死亡']::text[], 'hdcs', true),
  ('zhifu', '知府', 'townsfolk', '每个夜晚*，你会得知今天是否有非镇民且非旅行者的玩家死亡。', '府', array['客死他乡']::text[], 'hdcs', true),
  ('jiubao', '酒保', 'outsider', '与你邻近的善良玩家（旅行者除外）之一醉酒，即使你死于处决。', '保', array['醉酒']::text[], 'hdcs', true),
  ('rulianshi', '入殓师', 'outsider', '如果你提名了恶魔且他死于这次处决，你会变成那个邪恶的恶魔。当剩余存活玩家小于等于四人时（旅行者除外），你失去能力。', '殓', array['是恶魔']::text[], 'hdcs', true),
  ('huapi', '画皮', 'minion', '在你的首个夜晚，你要选择一名存活玩家：他死亡但会被当作存活。当他下一次即将死亡时，他重生，随后你重获能力。', '画', array['以为存活', '重获能力']::text[], 'hdcs', true),
  ('gudiao', '蛊雕', 'minion', '每个夜晚，你会得知顺时针方向上的下一名存活的镇民玩家的角色，他中毒且可能被当作邪恶的蛊雕，直到下个黄昏。每局游戏限一次，在夜晚时，你可以改变方向。', '雕', array['蛊毒', '改变方向']::text[], 'hdcs', true),
  ('mengpo', '孟婆', 'minion', '每个夜晚*，你可以选择一名存活玩家，他要二选一：1）能力描述修改为“你没有能力。”；2）死亡并保留能力直到下个黄昏。', '孟', array['没有能力', '保留能力']::text[], 'hdcs', true),
  ('niangjiushi', '酿酒师', 'minion', '每个夜晚，你要选择一个镇民角色：当他下一次通过自身能力获取信息时，改为得知你给出的信息。', '酿', array['微醺']::text[], 'hdcs', true),
  ('baojun', '暴君', 'demon', '每个夜晚*，你要选择一名玩家：他死亡。如果你杀死了与爪牙邻近的玩家，下个夜晚你可以选择至多两名玩家：他们死亡。', '暴', array['死亡', '暴虐']::text[], 'hdcs', true),
  ('dianyuzhang', '典狱长', 'demon', '每个夜晚，你要选择至多三名玩家：如果明天白天他们之一死于处决，上次被你选择的其他玩家会在当晚死亡。否则，当晚他们之中会有一名玩家死亡。', '典', array['判罚', '死于今日', '死亡']::text[], 'hdcs', true),
  ('guhuoniao', '姑获鸟', 'demon', '每个夜晚*，你要选择一名玩家：他死亡。每局游戏限一次，当爪牙死于处决时，你可能会获得他的能力。', '姑', array['死亡', '获得能力']::text[], 'hdcs', true),
  ('jianning', '奸佞', 'demon', '每个夜晚*，你要选择一名玩家：他死亡。爪牙在其死亡的当晚要选择一名玩家：如果他是善良的，他死亡。', '奸', array['爪牙死亡', '死亡']::text[], 'hdcs', true),
  ('xizi_gai', '戏子（改）', 'townsfolk', '其他善良玩家醉酒（旅行者除外），你们互相认识且无法转变阵营，对调胜负结果，即使你失去能力。', '戏', array[]::text[], 'hdcs', true),
  ('jinweijun_gai', '禁卫军（改）', 'minion', '在你的首个夜晚，你要选择存活或死亡。“疯狂”地想要这样做的玩家可能会立即被处决。', '禁', array[]::text[], 'hdcs', true)
